namespace sv_22fe64fe40cb415895f86e12974b5e48;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@rendermode InteractiveServer

<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0d6efd");">
    @GetThemeIcon() @(Theme?.Theme.ToString() ?? "Light")
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetThemeIcon() => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width: 200px;"
            value="@theme.Theme" @onchange="OnThemeChanged">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <option value="@t">@t</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@theme.AccentColor" @onchange="OnAccentChanged" />
</div>

<div class="mt-4 p-3 border rounded" style="border-color: @theme.AccentColor !important;">
    <strong>Preview:</strong>
    <span style="color: @theme.AccentColor;">
        @GetThemeIcon() @theme.Theme mode with accent @theme.AccentColor
    </span>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private ThemeInfo theme = new();

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            theme = Theme;
        }
    }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var parsed))
        {
            theme.Theme = parsed;
            await ThemeSource.NotifyChangedAsync(theme);
        }
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        theme.AccentColor = e.Value?.ToString() ?? "#0d6efd";
        await ThemeSource.NotifyChangedAsync(theme);
    }

    private string GetThemeIcon() => theme.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

